/* Supplies campaign state to the original app.js renderer; never loads a Classic match. */
(function(){'use strict';const A=ArtifactCampaign,D=ArtifactCampaignData,I=ArtifactI18n,K=ArtifactCampaignDeck,T=I.T,pick=I.pick;
let profile;try{profile=JSON.parse(localStorage.getItem(A.SAVE_KEY));K.migrate(profile);if(!A.valid(profile)||!profile.battle)throw Error(T('请从剧情营地开始战斗','Start battles from the campaign camp'));}catch(e){location.replace('campaign.html');throw e;}
const game=new A.CampaignGame(ARTIFACT_CARDS);game.s=profile.battle;game.s.players[0].heroes=game.s.units.filter(u=>u.owner===0&&u.hero).map(u=>u.k);game.s.players[1].heroes=[...new Set(game.s.units.filter(u=>u.owner===1&&u.hero).map(u=>u.k))];
function scepter(){const s=game.s,pl=s.players[0];if(s.profile.scepter&&!s.scepterUsed&&!pl.hand.some(h=>h.k==='story_scepter'))pl.hand.push({uid:game.id(),k:'story_scepter',lock:0});}
document.body.classList.toggle('campaign-no-towers',!['defend','assault'].includes(game.scene().kind));
document.body.classList.add('campaign-native');
scepter();const cards=Object.values(game.cards);for(const c of cards)if(c.baseKey)c.text=K.describe(c,profile);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const LANES=[()=>T('上路','Top'),()=>T('中路','Mid'),()=>T('下路','Bot')];
window.ArtifactCampaignBridge={game,cards,
 save(state){const current=JSON.parse(localStorage.getItem(A.SAVE_KEY)||'null');if(current&&current.stage>state.chapter)return;profile.battle=state;profile.scene=state.scene;if(state.scepterUsed)profile.scepterUsed=true;scepter();localStorage.setItem(A.SAVE_KEY,JSON.stringify(profile));},
 header(){return `<header class="topbar"><a class="wordmark" href="campaign.html">◈ ${T('暗月残片','Dark Moon Shards')}</a><nav><a href="campaign.html">${T('返回旅程','Back to the journey')}</a><span>${T('单人剧情 · 因果构筑','Solo story · causality building')}</span></nav><div class="header-tools"><button class="icon-button" data-action="sound" aria-label="${T('切换声音','Toggle sound')}">♫</button><button class="icon-button" data-action="settings" aria-label="${T('设置','Settings')}">⚙</button><button data-action="log">${T('战斗记录','Battle log')}</button></div></header>`;},
 status(g){const st=g.stage(),sc=g.scene(),intent=g.s.pursuitIntent,sent=g.scene().kind==='sentry'?g.all(1).filter(u=>g.flag(u,'sentry')):null;return `<div class="campaign-objective"><b>${esc(pick(st,'title'))}${A.sceneCount(st)>1?` · ${T('第 '+(g.s.scene+1)+'/'+A.sceneCount(st)+' 幕','Scene '+(g.s.scene+1)+'/'+A.sceneCount(st))}`:''}</b><span>${esc(pick(D.objectives[sc.kind],'name'))} · ${T('第 '+g.s.round+'/'+sc.rounds+' 轮','Round '+g.s.round+'/'+sc.rounds)}${['stealth','sentry'].includes(sc.kind)?' · '+T('警戒 ','Alarm ')+g.s.alarm+'/2':''}${sent&&sent.length?' · '+T('哨位 ','Sentry ')+sent.length:''}</span>${intent&&g.get(intent.unit)?.alive?`<strong class="pursuit-intent">${T('跳刀预告：下轮追杀 ','Blink telegraphed: next round it hunts in ')}${LANES[intent.lane]()} · ${T('控制追猎者可打断','control the hunter to interrupt')}</strong>`:''}</div>`;},
 endHTML(g){const won=g.s.winner===0,last=g.s.scene>=A.sceneCount(g.stage())-1;return `<div class="phase-overlay"><section class="end-panel"><div class="eyebrow">${won?(last?'CHAPTER COMPLETE':'SCENE CLEAR'):'JOURNEY INTERRUPTED'}</div><h2>${won?(last?T('此关告捷','Stage cleared'):T('此幕落幕','Scene cleared')):T('暂别此岸','Leave this shore, for now')}</h2><p>${esc(g.s.log.at(-1)?.text)}</p><div class="lobby-actions"><a class="primary" href="campaign.html">${won?(last?T('选择奖励 · 继续旅程','Choose a boon · continue'):T('进入下一幕','To the next scene')):T('返回营地 · 调整构筑','Back to camp · rebuild')}</a><button class="secondary" data-action="log">${T('查看战斗记录','View the battle log')}</button></div></section></div>`;},
 action(action){if(action==='confirm-surrender')game.emit('victory',T('主动撤退，关前成长与牌组保留','Withdrew — growth and deck from before the stage are kept'));if(['lobby','decks','collection','start','resume'].includes(action)){location.href='campaign.html';return true;}return false;}
};
})();
